from logging import getLogger

from .fixers import MissingMandatoryParamFixer, IncorrectValueFixer, MissingMandatoryManagedObjectFixer
from .fixers import MissingMandatoryListFixer, UnsupportedParameterFixer
from .xml import Scfc, ParamDictionary, ScfcValidationReport

from .sutool import ScfcParsingFailedOrInvalidSUToolArgs, NoScfdRuleFilesFound, SUToolWrapper


log = getLogger('ute_btssm.scfc')


class SCFCFixer(object):
    def __init__(self, btssm_cmd_builder):
        """
        :param BTSSMCommandBuilder btssm_cmd_builder: Object which is able to build BTSSM execution commands.
        """
        self._btssm_cmd_builder = btssm_cmd_builder
        self.fixers = [MissingMandatoryParamFixer(),
                       IncorrectValueFixer(),
                       MissingMandatoryListFixer(),
                       MissingMandatoryManagedObjectFixer(),
                       UnsupportedParameterFixer()]

    def fix_scfc_errors(self, input_scfc, output_scfc, feedback_file, dictionary_file):
        """Method will try to fix SCFC file based on provided feedback file and dictionary from BTSSM application.

        :param string input_scfc: Path to SCFC to fix.
        :param string output_scfc: Path to fixed SCFC file.
        :param string feedback_file: Path to validation feedback file.
        :param string dictionary_file: Path to parameters dictionary file from BTSSM application.
        """
        scfc = Scfc(input_scfc)
        dictionary = ParamDictionary(dictionary_file)
        validation_report = ScfcValidationReport(feedback_file)
        self._fix_messages(validation_report, dictionary, scfc)
        scfc.save(output_scfc)

    def _fix_messages(self, validation_report, dictionary, scfc):
        for validation_message in validation_report:
            self._fix_message(validation_message, dictionary, scfc)

    def _fix_message(self, validation_message, dictionary, scfc):
        for fixer in self.fixers:
            if fixer.can_fix(validation_message):
                try:
                    fixer.fix(validation_message, dictionary, scfc)
                except Exception as e:
                    self._log_fix_failed(validation_message, e)
                else:
                    return
        self._log_not_fixed(validation_message)

    def _log_not_fixed(self, validation_message):
        pass  # TODO

    def _log_fix_failed(self, validation_message, e):
        print(e)  # TODO

    def migrate_scfc_using_sutool(self, scfc_path, output_path, scfds_source='active partition', enb_ip='192.168.255.129',
                                  log_path='', ignore_errors=True):
        """Migrates given SCFC file using SUTool.

        :param string scfc_path: Path to the SCFC file.
        :param string output_path: Path where the migrated SCFC should be saved.
        :param string scfds_source: Source for SCFD files (the migration rules) and for the AdaptationVersions file (TL17/FL17+ only).
        :param string ignore_errors: If set to true (the default), errors will not cause the keyword to fail and have to be handled manually
                                     based on the returned code. If set to false, the keyword will raise an error if SUTool fails to read
                                     the input SCFC or if no SCFD files are found.
        :returns: Return code of SUTool.
        """
        return_code = SUToolWrapper().migrate_scfc_locally(scfc_path,
                                                           output_path,
                                                           scfds_source=scfds_source,
                                                           enb_ip=enb_ip,
                                                           log_path=log_path)
        if not ignore_errors and return_code.invalid_args_or_parsing_failed:
            raise ScfcParsingFailedOrInvalidSUToolArgs([scfc_path, output_path, scfds_source, log_path])
        elif not ignore_errors and return_code.no_rule_files_found:
            raise NoScfdRuleFilesFound(scfds_source)
        else:
            return return_code
